};

// ---- college work summary: every open task in the College space, grouped by how soon it is due ----
function collegeSummary(tasks, now) {
  const today = istDateStr(now);
  const g = { overdue: [], today: [], upcoming: [], none: [] };
  for (const t of Array.isArray(tasks) ? tasks : []) {
    if (!t || !t.title) continue;
    if (!t.due_at) { g.none.push(t); continue; }
    const day = istDateStr(new Date(t.due_at));
    (day < today ? g.overdue : day === today ? g.today : g.upcoming).push(t);
  }
  const byDue = (a, b) => new Date(a.due_at).getTime() - new Date(b.due_at).getTime();
  g.overdue.sort(byDue); g.today.sort(byDue); g.upcoming.sort(byDue);
  const total = g.overdue.length + g.today.length + g.upcoming.length + g.none.length;
  const names = (list, n) => list.slice(0, n).map((t) => t.title).join(', ') + (list.length > n ? ` and ${list.length - n} more` : '');
  const parts = [];
  if (g.overdue.length) parts.push(`${g.overdue.length} overdue: ${g.overdue.slice(0, 3).map((t) => `${t.title}, due ${speakWhen(new Date(t.due_at), now, true)}`).join('; ')}${g.overdue.length > 3 ? `; and ${g.overdue.length - 3} more` : ''}`);
  if (g.today.length) parts.push(`${g.today.length} due today: ${names(g.today, 3)}`);
  if (g.upcoming.length) parts.push(`next up: ${g.upcoming.slice(0, 2).map((t) => `${t.title} ${speakWhen(new Date(t.due_at), now, true)}`).join('; ')}${g.upcoming.length > 2 ? `; ${g.upcoming.length - 2} more later` : ''}`);
  if (g.none.length) parts.push(`${g.none.length} with no due date`);
  const spoken = total ? `You have ${total} open college ${total === 1 ? 'task' : 'tasks'}. ${parts.join('. ')}.` : 'You have no open college work.';
  const top = [...g.overdue, ...g.today, ...g.upcoming, ...g.none].slice(0, 6).map((t) => ({ id: t.id, title: t.title, due_at: t.due_at || null }));
  return { total, overdue: g.overdue.length, today: g.today.length, upcoming: g.upcoming.length, none: g.none.length, top, spoken };
}

